/* Build the shell command for one stage run.

   This is the only place a caller-supplied value reaches a shell, so quoting
   happens here and nowhere else.

   A cohort key is "campaign|YYYY-MM-DD". That pipe is a shell pipe: passing
   --cohort bucket|2026-08-13 unquoted would run "--cohort bucket" and pipe its
   output into a command named 2026. Every token is therefore single-quoted
   individually — harmless for flags, mandatory for values. */

const inp = $input.first().json;
const stage = String(inp.stage ?? '').trim();
const month = String(inp.month ?? '').trim();
const label = String(inp.label ?? '').trim() || ('stage ' + stage);

/* Reject rather than pass through. A malformed stage or month here means the
   caller has a bug, and running SOMETHING is worse than running nothing. */
if (!/^[0-9]{2}$/.test(stage)) throw new Error('stage must be two digits ("00".."07"), got: ' + JSON.stringify(inp.stage));
if (!/^[0-9]{4}-[0-9]{2}$/.test(month)) throw new Error('month must be YYYY-MM, got: ' + JSON.stringify(inp.month));

const repo = $vars.RBL_REPO;
if (!repo) throw new Error('n8n variable RBL_REPO is not set — see n8n/SETUP_MONTH_PIPELINE.md');

/* args is an array of tokens (preferred — a value containing a space survives)
   or a string, split on whitespace. No flag the pipeline takes today has a
   space in its value, so the string form is safe; the array form is there for
   when one does. */
let args = inp.args ?? [];
if (typeof args === 'string') args = args.trim() ? args.trim().split(/\s+/) : [];
if (!Array.isArray(args)) throw new Error('args must be a string or an array of tokens');

const q = (s) => "'" + String(s).replace(/'/g, "'\\''") + "'";

/* --silent keeps npm's own banner off stdout. The parser takes the last line
   beginning with "{" either way, but a clean stdout is easier to read in the
   execution log when something has gone wrong. */
/* THE SENTINEL IS NOT OPTIONAL, AND HERE IS THE MEASUREMENT.
   Observed on n8n 2.35.7, Execute Command node typeVersion 1:

     exit 0            -> { exitCode: 0, stdout: "...", stderr: "..." }
     exit 10, stderr   -> { error: "<the stderr text>" }
     exit 10, no stderr-> { error: "Command failed with exit code 10" }
     exit 1            -> { error: "<the stderr text>" }

   On ANY non-zero exit the node discards exitCode AND stdout and puts stderr
   into `error`. Exit 10 and exit 1 are then indistinguishable, because every
   stage writes progress to stderr through ctx.log — so the code is always
   lost, and the JSON line the whole contract is built on is lost with it.
   Un-sentinelled, every month containing a decision routes to the error
   handler as a crash. `onError: continueRegularOutput` does not help: it keeps
   the workflow running, it does not restore the fields.

   So the command must never exit non-zero. Wrapping the pipeline in ( ) and
   following it with printf makes printf the last command, the shell exits 0,
   and the real code travels in stdout where nothing can strip it. This is the
   __EXIT__ sentinel the old rbl-month workflow used; dropping it was based on
   a belief about this node that is true only for exit 0.

   The sentinel line does not begin with "{", so the "last line starting with
   {" parser in Classify still finds the JSON. */
const inner = 'cd ' + q(repo)
  + ' && npm run pipeline --silent -- --stage ' + q(stage)
  + ' --month ' + q(month)
  + ' --json'
  + (args.length ? ' ' + args.map(q).join(' ') : '');

const command = '( ' + inner + " ); printf '__EXIT__%s\\n' \"$?\"";

return [{ json: { stage, month, label, args, command, startedAt: Date.now() } }];

/* THE ONLY COPY of parse-and-classify in the whole system.

   The workflow this replaces carried these same lines seven times, once per
   stage (HANDOFF_N8N_MAX.md §1, gap #2). A fix to exit-code handling had to be
   made in seven places, and the eighth stage would have been written from
   memory. Every stage now comes through here, so the contract is interpreted
   identically everywhere and a fix lands once.

   It also drops the old __EXIT__$? sentinel. The Execute Command node reports
   the real exit code on its own output; echoing it into stdout and parsing it
   back was a workaround for a problem n8n does not have, and it broke on any
   stage whose output did not end exactly where the sentinel expected. */

const cmd = $('Run stage').first().json;
const meta = $('Build command').first().json;

/* THE SENTINEL IS THE ONLY RELIABLE SOURCE OF THE EXIT CODE.
   Measured on n8n 2.35.7: the Execute Command node reports `exitCode` only when
   the command exits 0. On any non-zero exit it emits `{ error }` alone — no
   exitCode, no stdout — with the stderr text as the error message, which makes
   an exit 10 identical to an exit 1. Build command therefore wraps the stage so
   the shell always exits 0 and prints `__EXIT__<code>` on stdout.

   Order of trust:
     1. the __EXIT__ sentinel   — survives every case
     2. cmd.exitCode            — correct, but only ever present for 0
     3. cmd.error ? 1 : 0       — last resort, and it CANNOT tell 10 from 1,
                                  so it is reported as a contract violation
                                  rather than quietly treated as a crash. */
const stdoutRaw = String(cmd.stdout ?? '');
const sentinel = [...stdoutRaw.matchAll(/^__EXIT__(\d+)\s*$/gm)].pop();

let exitCode;
let exitCodeSource;
if (sentinel) {
  exitCode = Number(sentinel[1]);
  exitCodeSource = 'sentinel';
} else if (Number.isFinite(Number(cmd.exitCode))) {
  exitCode = Number(cmd.exitCode);
  exitCodeSource = 'node';
} else {
  exitCode = cmd.error ? 1 : 0;
  exitCodeSource = 'inferred';
}

/* Keep the sentinel out of everything downstream reads. */
const stdout = stdoutRaw.replace(/^__EXIT__\d+\s*$/gm, '');
const stderr = String(cmd.stderr ?? '') + (cmd.error ? '\n' + String(cmd.error) : '');
const stderrTail = stderr.slice(-2000);

const jsonLine = stdout.split('\n').map((l) => l.trim()).filter((l) => l.startsWith('{')).pop() || null;
let json = null;
let parseError = null;
if (jsonLine) {
  try { json = JSON.parse(jsonLine); } catch (e) { parseError = e.message; }
}

/* 0 = done · 10 = a human must decide · anything else = crash.
   A 10 is the pipeline working correctly and must never render red — hard rule
   #5. This node only labels it; RBL · Notify colours it and the caller decides
   what it means. */
let outcome = exitCode === 0 ? 'done' : exitCode === 10 ? 'stop' : 'crash';
let contractViolation = null;

/* No sentinel and no exitCode means the code was inferred from the presence of
   an error string, and that inference cannot distinguish "a human must decide"
   from "the stage died". Say so rather than let a decision be filed as a crash
   — which is exactly what happened before the sentinel was restored. */
if (exitCodeSource === 'inferred') {
  outcome = 'crash';
  contractViolation = 'stage ' + meta.stage + ' produced no __EXIT__ sentinel and no exitCode, so the real exit code is unknown'
    + ' — an exit 10 (a human must decide) is indistinguishable from a crash in this shape. Check that Build command still'
    + ' appends the sentinel; see the measurement in its comment.';
}

if (!jsonLine) {
  if (outcome !== 'crash') {
    /* Exiting 0 or 10 means the stage believes it finished, and a finished
       stage's last stdout line is its JSON. Nothing downstream can proceed on
       a claim with no payload. */
    outcome = 'crash';
    contractViolation = 'stage ' + meta.stage + ' exited ' + exitCode
      + ' but printed no JSON line on stdout — that is itself a contract violation and is reported as a crash';
  }
  /* else: allowed. A stage that died before printing has nothing to print, and
     the stderr tail is what the operator reads instead. */
} else if (parseError) {
  outcome = 'crash';
  contractViolation = 'stage ' + meta.stage + ' printed a last JSON line that does not parse ('
    + parseError + ') — that is itself a contract violation and is reported as a crash';
}

/* The uniform envelope. No branching here: the caller decides what a stop
   means in its context (§3.1). */
return [{
  json: {
    ok: outcome === 'done',
    stage: meta.stage,
    month: meta.month,
    label: meta.label,
    exitCode,
    exitCodeSource,
    outcome,
    json,
    contractViolation,
    stderrTail,
    durationMs: Date.now() - Number(meta.startedAt || Date.now()),
  },
}];
